command -v runuser >/dev/null 2>&1 || exit 127; runuser -u dnsmasq -- env HOME=/var/lib/misc XDG_RUNTIME_DIR=/run/user/999 sh -c 'scope="$HOME/.local/share/flatpak"; test -d "$scope" || { printf "%s\n" "Default user Flatpak scope does not exist or is inaccessible" >&2; exit 125; }; FLATPAK_USER_DIR="$scope" flatpak --user list --runtime --columns=ref,version,origin'
